{
	writer.write(value.valUint8);writer.write(value.valInt8);writer.write(value.valUint16);writer.write(value.valInt16);writer.write(value.valUint32);writer.write(value.valInt32);writer.write(value.valUint64);writer.write(value.valInt64);writer.write(value.valString);writer.write(value.valArrayString);writer.write(value.valMapStringFloat32);writer.write(value.valTimestamp);writer.write(value.valEnum);writer.write(value.valListEnum);writer.write(value.valMapEnumString);writer.write(value.valMapStringEnum);writer.write(value.valEmpty);writer.write(value.valNestedEmpty);writer.write(value.valByteArray);writer.write(value.valUUID);
}

