	if (err) {
		return err;
	}
	err = reader.read(value.valInt64);
	if (err) {
		return err;
	}
	err = reader.read(value.valString);
	if (err) {
		return err;
	}
	err = reader.read(value.valArrayString);
	if (err) {
		return err;
	}
	err = reader.read(value.valMapStringFloat32);
	if (err) {
		return err;
	}
	err = reader.read(value.valTimestamp);
	if (err) {
		return err;
	}
	err = reader.read(value.valEnum);
	if (err) {
		return err;
	}
	err = reader.read(value.valListEnum);
	if (err) {
		return err;
	}
	err = reader.read(value.valMapEnumString);
	if (err) {
		return err;
	}
	err = reader.read(value.valMapStringEnum);
